import{_ as t,a0 as p,w as o,s as r,ao as c,I as a,x as n,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 服务器上设置 ulimit 和文件描述符数限制 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 服务器上设置 ulimit 和文件描述符数限制 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 服务器上设置 ulimit 和文件描述符数限制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 服务器上设置 ulimit 和文件描述符数限制 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers","title":"如何在 Linux 服务器上设置 ulimit 和文件描述符数限制","tag":"201907","desc":""},"relativePath":"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers.md","filePath":"[post].md"}'),d={name:"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers.md"};function u(h,s,m,g,b,k){const i=p("Link");return o(),r("div",null,[s[18]||(s[18]=c(`<h1 id="如何在-linux-服务器上设置-ulimit-和文件描述符数限制" tabindex="-1">如何在 Linux 服务器上设置 ulimit 和文件描述符数限制 <a class="header-anchor" href="#如何在-linux-服务器上设置-ulimit-和文件描述符数限制" aria-label="Permalink to “如何在 Linux 服务器上设置 ulimit 和文件描述符数限制”">​</a></h1><p><strong>简介</strong>：在生产环境中遇到打开文件数这类的挑战如今已是司空见惯的事情了。因为许多应用程序是基于 Java 和 Apache 的，安装和配置它们可能会导致打开过多的文件（文件描述符）。如果打开的文件描述符超过了默认设置的限制，就可能会面临访问控制问题，受阻于打开文件的挑战。许多生产环境因此而陷入停滞状态。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201907/09/121422bv6t76nztjxqoprn.jpg" alt=""></p><p>幸运的是，在基于 Linux 的服务器上，都有 <code>ulimit</code> 命令，通过它可以查看、设置、获取文件打开的状态和配置详情。此命令配备了许多选项，通过这些组合可以设置打开文件的数量。下面逐个命令用示例做了详细说明。</p><h3 id="查看任何-linux-系统中当前打开文件数的限制" tabindex="-1">查看任何 Linux 系统中当前打开文件数的限制 <a class="header-anchor" href="#查看任何-linux-系统中当前打开文件数的限制" aria-label="Permalink to “查看任何 Linux 系统中当前打开文件数的限制”">​</a></h3><p>要在 Linux 服务器上得到打开文件数的限制，请执行以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@ubuntu ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>146013</span></span></code></pre></div><p>上面的数字表明用户可以在每个用户登录会话中打开 ‘146013’ 个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@centos ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>149219</span></span>
<span class="line"><span>[root@debian ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>73906</span></span></code></pre></div><p>这清楚地表明，各个 Linux 操作系统具有不同的打开文件数限制。这基于各自系统中运行的依赖关系和应用程序。</p><h3 id="ulimit-命令" tabindex="-1">ulimit 命令 <a class="header-anchor" href="#ulimit-命令" aria-label="Permalink to “ulimit 命令”">​</a></h3><p>顾名思义，<code>ulimit</code>（用户限制）用于显示和设置登录用户的资源限制。当我们使用 <code>-a</code> 选项运行 <code>ulimit</code> 命令时，它将打印登录用户的所有资源限制。现在让我们在 Ubuntu/Debian 和 CentOS 系统上运行 <code>ulimit -a</code>，</p><h4 id="ubuntu-debian-系统" tabindex="-1">Ubuntu / Debian 系统 <a class="header-anchor" href="#ubuntu-debian-系统" aria-label="Permalink to “Ubuntu / Debian 系统”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@Ubuntu ~}$ ulimit -a</span></span>
<span class="line"><span>core file size          (blocks, -c) 0</span></span>
<span class="line"><span>data seg size           (kbytes, -d) unlimited</span></span>
<span class="line"><span>scheduling priority             (-e) 0</span></span>
<span class="line"><span>file size               (blocks, -f) unlimited</span></span>
<span class="line"><span>pending signals                 (-i) 5731</span></span>
<span class="line"><span>max locked memory       (kbytes, -l) 64</span></span>
<span class="line"><span>max memory size         (kbytes, -m) unlimited</span></span>
<span class="line"><span>open files                      (-n) 1024      </span></span>
<span class="line"><span>pipe size            (512 bytes, -p) 8</span></span>
<span class="line"><span>POSIX message queues     (bytes, -q) 819200</span></span>
<span class="line"><span>real-time priority              (-r) 0</span></span>
<span class="line"><span>stack size              (kbytes, -s) 8192</span></span>
<span class="line"><span>cpu time               (seconds, -t) unlimited</span></span>
<span class="line"><span>max user processes              (-u) 5731</span></span>
<span class="line"><span>virtual memory          (kbytes, -v) unlimited</span></span>
<span class="line"><span>file locks                      (-x) unlimited</span></span></code></pre></div><h4 id="centos-系统" tabindex="-1">CentOS 系统 <a class="header-anchor" href="#centos-系统" aria-label="Permalink to “CentOS 系统”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@centos ~}$ ulimit -a</span></span>
<span class="line"><span>core file size          (blocks, -c) 0</span></span>
<span class="line"><span>data seg size           (kbytes, -d) unlimited</span></span>
<span class="line"><span>scheduling priority             (-e) 0</span></span>
<span class="line"><span>file size               (blocks, -f) unlimited</span></span>
<span class="line"><span>pending signals                 (-i) 5901</span></span>
<span class="line"><span>max locked memory       (kbytes, -l) 64</span></span>
<span class="line"><span>max memory size         (kbytes, -m) unlimited</span></span>
<span class="line"><span>open files                      (-n) 1024</span></span>
<span class="line"><span>pipe size            (512 bytes, -p) 8</span></span>
<span class="line"><span>POSIX message queues     (bytes, -q) 819200</span></span>
<span class="line"><span>real-time priority              (-r) 0</span></span>
<span class="line"><span>stack size              (kbytes, -s) 8192</span></span>
<span class="line"><span>cpu time               (seconds, -t) unlimited</span></span>
<span class="line"><span>max user processes              (-u) 5901</span></span>
<span class="line"><span>virtual memory          (kbytes, -v) unlimited</span></span>
<span class="line"><span>file locks                      (-x) unlimited</span></span></code></pre></div><p>正如我们可以在这里看到的，不同的操作系统具有不同的限制设置。所有这些限制都可以使用 <code>ulimit</code> 命令进行配置/更改。</p><p>要显示单个资源限制，可以在 <code>ulimit</code> 命令中传递特定的参数，下面列出了一些参数：</p><ul><li><code>ulimit -n</code> –&gt; 显示打开文件数限制</li><li><code>ulimit -c</code> –&gt; 显示核心转储文件大小</li><li><code>umilit -u</code> –&gt; 显示登录用户的最大用户进程数限制</li><li><code>ulimit -f</code> –&gt; 显示用户可以拥有的最大文件大小</li><li><code>umilit -m</code> –&gt; 显示登录用户的最大内存大小</li><li><code>ulimit -v</code> –&gt; 显示最大内存大小限制</li></ul><p>使用以下命令检查登录用户打开文件数量的硬限制和软限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@Ubuntu ~}$ ulimit -Hn</span></span>
<span class="line"><span>1048576</span></span>
<span class="line"><span>shashi@Ubuntu ~}$ ulimit -Sn</span></span>
<span class="line"><span>1024</span></span></code></pre></div><h3 id="如何修复达到最大文件数限制的问题" tabindex="-1">如何修复达到最大文件数限制的问题？ <a class="header-anchor" href="#如何修复达到最大文件数限制的问题" aria-label="Permalink to “如何修复达到最大文件数限制的问题？”">​</a></h3><p>让我们假设我们的 Linux 服务器已经达到了打开文件的最大数量限制，并希望在系统范围扩展该限制，例如，我们希望将 100000 设置为打开文件数量的限制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# sysctl -w fs.file-max=100000</span></span>
<span class="line"><span>fs.file-max = 100000</span></span></code></pre></div><p>上述更改将在下次重启之前有效，因此要使这些更改在重启后仍存在，请编辑文件 <code>/etc/sysctl.conf</code> 并添加相同的参数，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# vi /etc/sysctl.conf</span></span>
<span class="line"><span>fs.file-max = 100000</span></span></code></pre></div><p>保存文件并退出。</p><p>运行下面命令，使上述更改立即生效，而无需注销和重新启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# sysctl -p</span></span></code></pre></div><p>现在验证新的更改是否生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>100000</span></span></code></pre></div><p>使用以下命令找出当前正在使用的文件描述符数量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@ansible ~]# more /proc/sys/fs/file-nr</span></span>
<span class="line"><span>1216    0       100000</span></span></code></pre></div><p>注意：命令 <code>sysctl -p</code> 用于在不重新启动和注销的情况下提交更改。</p><h3 id="通过-limit-conf-文件设置用户级资源限制" tabindex="-1">通过 limit.conf 文件设置用户级资源限制 <a class="header-anchor" href="#通过-limit-conf-文件设置用户级资源限制" aria-label="Permalink to “通过 limit.conf 文件设置用户级资源限制”">​</a></h3><p><code>/etc/sysctl.conf</code> 文件用于设置系统范围的资源限制，但如果要为 Oracle、MariaDB 和 Apache 等特定用户设置资源限制，则可以通过 <code>/etc/security/limits.conf</code> 文件去实现。</p><p>示例 <code>limits.conf</code> 如下所示，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# cat /etc/security/limits.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Limits-conf-linux-part1-1024x677.jpg" alt="Limits-conf-linux-part1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Limits-conf-linux-part2-1024x443.jpg" alt="Limits-conf-linux-part2"></p><p>假设我们要为 linuxtechi 用户设置打开文件数量的硬限制和软限制，而对于 oracle 用户设置打开进程数量的硬限制和软限制，编辑文件 <code>/etc/security/limits.conf</code> 并添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hard limit for max opened files for linuxtechi user</span></span>
<span class="line"><span>linuxtechi       hard    nofile          4096</span></span>
<span class="line"><span># soft limit for max opened files for linuxtechi user</span></span>
<span class="line"><span>linuxtechi       soft    nofile          1024</span></span>
<span class="line"><span></span></span>
<span class="line"><span># hard limit for max number of process for oracle user</span></span>
<span class="line"><span>oracle           hard    nproc          8096</span></span>
<span class="line"><span># soft limit for max number of process for oracle user</span></span>
<span class="line"><span>oracle           soft    nproc          4096</span></span></code></pre></div><p>保存文件并退出。</p><p><strong>注意：</strong> 如果你想对一个组而不是用户进行资源限制，那么也可以通过 <code>limits.conf</code> 文件，输入 <code>@&lt;组名&gt;</code> 代替用户名，其余项都是相同的，示例如下，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hard limit for max opened files for sysadmin group</span></span>
<span class="line"><span>@sysadmin        hard         nofile            4096 </span></span>
<span class="line"><span># soft limit for max opened files for sysadmin group</span></span>
<span class="line"><span>@sysadmin        soft         nofile            1024</span></span></code></pre></div><p>验证新的更改是否生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# su - linuxtechi</span></span>
<span class="line"><span>~]$ ulimit -n -H</span></span>
<span class="line"><span>4096</span></span>
<span class="line"><span>~]$ ulimit -n -S</span></span>
<span class="line"><span>1024</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~]# su - oracle</span></span>
<span class="line"><span>~]$ ulimit -H -u</span></span>
<span class="line"><span>8096</span></span>
<span class="line"><span>~]$ ulimit -S -u</span></span>
<span class="line"><span>4096</span></span></code></pre></div>`,47)),a("p",null,[s[1]||(s[1]=n("注：其他主要使用的命令是 ",-1)),e(i,{href:"https://www.linuxtechi.com/lsof-command-examples-linux-geeks/"},{default:l(()=>[...s[0]||(s[0]=[n("lsof",-1)])]),_:1}),s[2]||(s[2]=n("，可用于找出“当前打开了多少个文件”，这命令对管理员非常有帮助。",-1))]),s[19]||(s[19]=a("h3",{id:"结尾",tabindex:"-1"},[n("结尾 "),a("a",{class:"header-anchor",href:"#结尾","aria-label":"Permalink to “结尾”"},"​")],-1)),s[20]||(s[20]=a("p",null,[n("正如在介绍部分提到的，"),a("code",null,"ulimit"),n(" 命令非常强大，可以帮助用户配置并确保应用程序安装更加流畅而没有任何瓶颈。此命令有助于修复基于 Linux 的服务器中的（打开）大量文件的限制。")],-1)),s[21]||(s[21]=a("hr",null,null,-1)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/set-ulimit-file-descriptors-limit-linux-servers/"},{default:l(()=>[...s[3]||(s[3]=[n("https://www.linuxtechi.com/set-ulimit-file-descriptors-limit-linux-servers/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:l(()=>[...s[5]||(s[5]=[n("Shashidhar Soppin",-1)])]),_:1}),s[10]||(s[10]=n(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),e(i,{href:"https://github.com/zgj1024"},{default:l(()=>[...s[7]||(s[7]=[n("zgj1024",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const C=t(d,[["render",u]]);export{y as __pageData,C as default};
